<?php

declare(strict_types=1);

use RefactorCircus\Ringside\AgentKitMigrator;
use RefactorCircus\Ringside\Config;
use RefactorCircus\Ringside\Project;
use RefactorCircus\Ringside\Render\ManagedBlock;

function agentKitInstall(): Project
{
    $project = fixtureProject([
        'agent-kit.yml' => "# agent-kit configuration.\nworkspace: { packages: [], jobs_dir: .agent-kit/jobs }\ncommands:\n  verify: composer test\n",
        '.claude/skills/agent-kit-factory/SKILL.md' => "---\nname: agent-kit-factory\n---\n<!-- generated by agent-kit 0.5.0; do not edit. -->\n",
        '.claude/skills/agent-kit-mine/SKILL.md' => "my own skill\n",
        '.claude/agents/agent-kit-implementer.md' => "<!-- generated by agent-kit 0.5.0; do not edit. -->\n",
        '.claude/settings.json' => json_encode(['permissions' => ['allow' => ['Bash(git *)']], 'hooks' => ['SessionStart' => [['matcher' => 'startup', 'hooks' => [['type' => 'command', 'command' => 'php vendor/refactor-circus/agent-kit/bin/agent-kit-hook session-start']]]], 'PostToolUse' => [['matcher' => 'Edit', 'hooks' => [['type' => 'command', 'command' => 'mine.sh']]]]]]),
        'AGENTS.md' => "# Pkg\n\n<!-- agent-kit:start -->\nold\n<!-- agent-kit:end -->\n",
        '.gitignore' => "/vendor\n\n# agent-kit generated files\n/.claude/skills/agent-kit-*/\n/.claude/agents/agent-kit-*.md\n/.agent-kit/\n",
        '.agent-kit/jobs/.gitkeep' => '',
        'composer.json' => json_encode(['require-dev' => ['refactor-circus/agent-kit' => '*']], JSON_UNESCAPED_SLASHES),
    ]);
    unlink($project->path(Config::FILE));

    return new Project($project->root);
}

it('detects an agent-kit install', function () {
    expect((new AgentKitMigrator)->needed(agentKitInstall()))->toBeTrue()
        ->and((new AgentKitMigrator)->needed(fixtureProject([])))->toBeFalse();
});

it('moves an agent-kit install to the Ring Master names', function () {
    $project = agentKitInstall();
    unlink($project->path('.agent-kit/jobs/.gitkeep'));

    $log = (new AgentKitMigrator)->migrate($project);
    $project = new Project($project->root);
    $settings = json_decode((string) $project->read('.claude/settings.json'), true);

    expect($project->exists('agent-kit.yml'))->toBeFalse()
        ->and((string) $project->read(Config::FILE))->toContain('Ring Master configuration', 'jobs_dir: .ring-master/jobs')
        ->and($project->config->string('commands.verify'))->toBe('composer test')
        ->and(is_dir($project->path('.ring-master')))->toBeTrue()
        ->and(is_dir($project->path('.agent-kit')))->toBeFalse()
        ->and($project->exists('.claude/skills/agent-kit-factory/SKILL.md'))->toBeFalse()
        ->and($project->exists('.claude/agents/agent-kit-implementer.md'))->toBeFalse()
        ->and($project->exists('.claude/skills/agent-kit-mine/SKILL.md'))->toBeTrue()
        ->and($settings['hooks'])->toHaveKey('PostToolUse')->not->toHaveKey('SessionStart')
        ->and($settings['permissions']['allow'])->toBe(['Bash(git *)'])
        ->and((string) $project->read('AGENTS.md'))->toContain(ManagedBlock::START, ManagedBlock::END)->not->toContain('agent-kit:start')
        ->and((string) $project->read('.gitignore'))->toContain('/.claude/skills/ring-master-*/', '/.ring-master/')->not->toContain('agent-kit')
        ->and(implode("\n", $log))->toContain('composer remove --dev refactor-circus/agent-kit')
        ->and((new AgentKitMigrator)->needed($project))->toBeFalse();
});

it('keeps the jobs folder while jobs are still in it, and changes nothing on a dry run', function () {
    $project = agentKitInstall();
    mkdir($project->path('.agent-kit/jobs/2026-10-23-import'));

    $dry = (new AgentKitMigrator)->migrate($project, dryRun: true);

    expect($project->exists('agent-kit.yml'))->toBeTrue()
        ->and($dry[0])->toStartWith('Would rename agent-kit.yml')
        ->and(implode("\n", (new AgentKitMigrator)->migrate($project)))->toContain('Kept .agent-kit/: 2 job folder(s)');
});
